import{_ as a,o as l,c as i,a3 as r}from"./chunks/framework.Bh_aNVBG.js";const o="/images/super-admin/image-76.png",e="/images/super-admin/image-77.png",d="/images/super-admin/image-78.png",n="/images/super-admin/image-79.png",s="/images/super-admin/image-80.png",h="/images/super-admin/image-81.png",p="/images/super-admin/image-82.png",g="/images/super-admin/image-83.png",b="/images/super-admin/image-84.png",c="/images/super-admin/image-85.png",u="/images/super-admin/image-86.png",I=JSON.parse('{"title":"8. 부가 서비스 설정 및 관리","description":"","frontmatter":{},"headers":[],"relativePath":"services.md","filePath":"services.md"}'),_={name:"services.md"};function m(q,t,k,x,f,P){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_8-부가-서비스-설정-및-관리" tabindex="-1">8. 부가 서비스 설정 및 관리 <a class="header-anchor" href="#_8-부가-서비스-설정-및-관리" aria-label="Permalink to &quot;8. 부가 서비스 설정 및 관리&quot;">​</a></h1><p>인포디오는 방문객에게 다양한 안내 서비스를 제공할 수 있도록 AI 챗봇, 설문조사, 오디오 가이드 및 비디오 가이드 기능을 지원합니다.</p><p>프로젝트 운영자는 행사 특성과 운영 목적에 따라 필요한 서비스를 활성화하고 관련 콘텐츠를 등록하여 사용할 수 있습니다.</p><h2 id="_8-1-부가-서비스-기능-안내" tabindex="-1">8.1. 부가 서비스 기능 안내 <a class="header-anchor" href="#_8-1-부가-서비스-기능-안내" aria-label="Permalink to &quot;8.1. 부가 서비스 기능 안내&quot;">​</a></h2><table tabindex="0"><thead><tr><th>서비스</th><th>설명</th><th>주요 활용 목적</th></tr></thead><tbody><tr><td>AI 챗봇</td><td>방문객의 질문에 대화형으로 응답하는 안내 서비스</td><td>행사 정보 및 장소 안내</td></tr><tr><td>설문조사</td><td>방문객의 의견을 수집하는 설문 기능</td><td>만족도 및 운영 의견 조사</td></tr><tr><td>오디오 가이드</td><td>음성으로 장소 및 콘텐츠 정보를 안내</td><td>전시·관광 해설, 위치 기반 음성 안내</td></tr><tr><td>비디오 가이드</td><td>영상으로 행사 및 콘텐츠 정보 안내</td><td>행사 소개, 시설 및 프로그램 안내</td></tr></tbody></table><h3 id="서비스-이용-전-확인사항" tabindex="-1">서비스 이용 전 확인사항 <a class="header-anchor" href="#서비스-이용-전-확인사항" aria-label="Permalink to &quot;서비스 이용 전 확인사항&quot;">​</a></h3><ol><li>프로젝트 관리 화면에 접속합니다.</li><li><strong>프로젝트 설정 &gt; 모듈</strong> 메뉴로 이동합니다.</li><li>사용할 부가 서비스 모듈이 활성화되어 있는지 확인합니다.</li><li>필요한 경우 해당 모듈을 활성화하고 저장합니다.</li><li>각 서비스 관리 화면에서 콘텐츠 및 세부 설정을 진행합니다.</li></ol><p><img src="'+o+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>서비스 모듈을 활성화하더라도 필요한 콘텐츠가 등록되지 않았거나 준비가 완료되지 않은 경우 방문객에게 서비스가 정상적으로 제공되지 않을 수 있습니다.</p></blockquote><hr><h2 id="_8-2-ai-챗봇-안내-서비스" tabindex="-1">8.2. AI 챗봇 안내 서비스 <a class="header-anchor" href="#_8-2-ai-챗봇-안내-서비스" aria-label="Permalink to &quot;8.2. AI 챗봇 안내 서비스&quot;">​</a></h2><p>AI 챗봇은 방문객이 행사와 관련된 정보를 질문하면 대화형으로 안내하는 서비스입니다.</p><p>방문객은 챗봇을 통해 행사 프로그램, 운영 정보, 장소 등에 관한 질문을 입력하고 답변을 확인할 수 있습니다.</p><h3 id="_1-ai-챗봇-활성화" tabindex="-1">① AI 챗봇 활성화 <a class="header-anchor" href="#_1-ai-챗봇-활성화" aria-label="Permalink to &quot;① AI 챗봇 활성화&quot;">​</a></h3><ol><li><strong>프로젝트 설정 &gt; 모듈</strong> 메뉴로 이동합니다.</li><li><strong>AI 챗봇</strong> 모듈을 활성화합니다.</li><li>변경 내용을 저장합니다.</li><li>필요에 따라 하단 내비게이션에 AI 챗봇 메뉴를 추가합니다.</li></ol><h3 id="_2-ai-챗봇-이용-예시" tabindex="-1">② AI 챗봇 이용 예시 <a class="header-anchor" href="#_2-ai-챗봇-이용-예시" aria-label="Permalink to &quot;② AI 챗봇 이용 예시&quot;">​</a></h3><p>방문객은 다음과 같은 질문을 입력하여 행사 관련 정보를 확인할 수 있습니다.</p><table tabindex="0"><thead><tr><th>질문 예시</th><th>안내 목적</th></tr></thead><tbody><tr><td>오늘 공연 일정 알려줘</td><td>행사 일정 안내</td></tr><tr><td>화장실이 어디 있어?</td><td>편의시설 위치 안내</td></tr><tr><td>체험 프로그램은 몇 시에 시작해?</td><td>프로그램 운영 정보 안내</td></tr><tr><td>행사장 주차장은 어디야?</td><td>교통 및 시설 안내</td></tr><tr><td>스탬프 투어는 어떻게 참여해?</td><td>참여형 서비스 안내</td></tr></tbody></table><h3 id="_3-ai-챗봇-운영-시-확인사항" tabindex="-1">③ AI 챗봇 운영 시 확인사항 <a class="header-anchor" href="#_3-ai-챗봇-운영-시-확인사항" aria-label="Permalink to &quot;③ AI 챗봇 운영 시 확인사항&quot;">​</a></h3><p>AI 챗봇을 운영하기 전에는 등록된 행사 정보가 최신 상태인지 확인하는 것이 좋습니다.</p><p>특히 다음 정보를 점검해 주세요.</p><ul><li>행사 일정 및 운영 시간</li><li>주요 장소와 시설 정보</li><li>행사 프로그램 및 상세 콘텐츠</li><li>공지사항 및 변경된 운영 정보</li></ul><blockquote><p><strong>주의사항</strong></p><p>AI 챗봇의 답변은 부정확하거나 실제 행사 운영 상황과 다를 수 있습니다.</p><p>행사 시작 전 주요 질문을 직접 테스트하고, 중요한 운영 정보가 정확하게 안내되는지 확인해 주세요.</p></blockquote><hr><h2 id="_8-3-설문조사-등록-및-관리" tabindex="-1">8.3. 설문조사 등록 및 관리 <a class="header-anchor" href="#_8-3-설문조사-등록-및-관리" aria-label="Permalink to &quot;8.3. 설문조사 등록 및 관리&quot;">​</a></h2><p>설문조사는 방문객을 대상으로 행사 만족도 및 다양한 의견을 수집하기 위한 기능입니다.</p><p>프로젝트 운영자는 설문 기간, 공개 여부, 질문 및 응답 유형 등을 설정할 수 있습니다.</p><p>설문은 여러 단계로 구분하여 구성할 수 있으며, 각 단계에 여러 질문을 등록할 수 있습니다.</p><h3 id="_1-설문조사-관리-화면-이동" tabindex="-1">① 설문조사 관리 화면 이동 <a class="header-anchor" href="#_1-설문조사-관리-화면-이동" aria-label="Permalink to &quot;① 설문조사 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>만족도 설문</strong> 메뉴를 선택합니다.</li><li>현재 등록된 설문 설정을 확인합니다.</li><li>필요한 설문 항목을 수정하거나 추가합니다.</li></ol><p><img src="'+e+'" alt="image.png"></p><h3 id="_2-설문-기본-설정" tabindex="-1">② 설문 기본 설정 <a class="header-anchor" href="#_2-설문-기본-설정" aria-label="Permalink to &quot;② 설문 기본 설정&quot;">​</a></h3><p>설문을 진행할 기간과 공개 여부 등을 설정합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>설문 기간</td><td>방문객이 설문에 참여할 수 있는 시작일과 종료일</td></tr><tr><td>공개</td><td>방문객에게 설문을 공개할지 설정</td></tr><tr><td>5점 척도 라벨</td><td>5점 척도형 질문에 공통으로 사용할 양 끝 문구</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li><strong>설문 설정</strong> 영역으로 이동합니다.</li><li>설문 시작일과 종료일을 입력합니다.</li><li>설문 공개 여부를 설정합니다.</li><li>필요한 경우 5점 척도 라벨을 입력합니다.</li><li>변경 내용을 저장합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>설문 종료일은 시작일보다 빠르게 설정할 수 없습니다.</p><p>설문 공개 여부와 기간을 확인한 후 방문객 화면에서 실제 참여가 가능한지 점검해 주세요.</p></blockquote><h3 id="_3-설문-단계-추가" tabindex="-1">③ 설문 단계 추가 <a class="header-anchor" href="#_3-설문-단계-추가" aria-label="Permalink to &quot;③ 설문 단계 추가&quot;">​</a></h3><p>설문은 여러 단계로 구분하여 구성할 수 있습니다.</p><p>예를 들어 첫 번째 단계는 행사 전반 만족도, 두 번째 단계는 프로그램 만족도, 세 번째 단계는 개선 의견으로 구성할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>설문 관리 화면에서 단계 목록을 확인합니다.</li><li><strong>+ 스텝 추가</strong> 버튼을 클릭합니다.</li><li>새로 생성된 단계를 선택합니다.</li><li>해당 단계에 질문을 등록합니다.</li><li>필요한 경우 드래그하여 단계 순서를 변경합니다.</li></ol><p><img src="'+d+'" alt="image.png"></p><h3 id="_4-설문-질문-등록" tabindex="-1">④ 설문 질문 등록 <a class="header-anchor" href="#_4-설문-질문-등록" aria-label="Permalink to &quot;④ 설문 질문 등록&quot;">​</a></h3><p>각 단계에는 여러 개의 질문을 등록할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>질문을 추가할 단계를 선택합니다.</li><li>질문 추가 기능을 선택합니다.</li><li>질문 내용을 입력합니다.</li><li>답변 유형을 선택합니다.</li><li>필요한 경우 응답 보기나 안내 문구를 입력합니다.</li><li>필수 응답 여부를 설정합니다.</li><li>변경 내용을 저장합니다.</li></ol><h3 id="_5-질문-답변-유형" tabindex="-1">⑤ 질문 답변 유형 <a class="header-anchor" href="#_5-질문-답변-유형" aria-label="Permalink to &quot;⑤ 질문 답변 유형&quot;">​</a></h3><table tabindex="0"><thead><tr><th>유형</th><th>설명</th><th>활용 예시</th></tr></thead><tbody><tr><td>단일 선택</td><td>여러 보기 중 하나 선택</td><td>방문 경로 조사</td></tr><tr><td>복수 선택</td><td>여러 보기 중 복수 항목 선택</td><td>참여 프로그램 조사</td></tr><tr><td>단답형</td><td>짧은 문장 또는 단어 입력</td><td>방문 목적 입력</td></tr><tr><td>서술형</td><td>자유로운 의견 작성</td><td>개선 의견 수집</td></tr><tr><td>별점</td><td>별점을 이용한 만족도 평가</td><td>행사 만족도</td></tr><tr><td>5점 척도</td><td>1~5점 기준 평가</td><td>운영 서비스 평가</td></tr></tbody></table><h3 id="_6-선택형-질문의-보기-등록" tabindex="-1">⑥ 선택형 질문의 보기 등록 <a class="header-anchor" href="#_6-선택형-질문의-보기-등록" aria-label="Permalink to &quot;⑥ 선택형 질문의 보기 등록&quot;">​</a></h3><p>단일 선택과 복수 선택 질문은 응답 보기를 직접 구성할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>질문의 답변 유형을 단일 선택 또는 복수 선택으로 설정합니다.</li><li><strong>+ 항목 추가</strong> 버튼을 클릭합니다.</li><li>보기에 표시할 내용을 입력합니다.</li><li>필요한 만큼 보기를 추가합니다.</li><li>자유로운 응답을 허용하려면 <strong>기타(직접입력)</strong> 옵션을 사용합니다.</li></ol><p><strong>질문 구성 예시</strong></p><p>질문: 이번 축제에 대한 정보를 어디서 확인하셨나요?</p><ul><li>공식 홈페이지</li><li>SNS</li><li>지인 추천</li><li>현장 홍보물</li><li>기타(직접입력)</li></ul><p><img src="'+n+'" alt="image.png"></p><h3 id="_7-5점-척도-설정" tabindex="-1">⑦ 5점 척도 설정 <a class="header-anchor" href="#_7-5점-척도-설정" aria-label="Permalink to &quot;⑦ 5점 척도 설정&quot;">​</a></h3><p>5점 척도형 질문에서는 평가의 양 끝에 표시되는 문구를 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>입력 예시</th></tr></thead><tbody><tr><td>왼쪽 끝</td><td>매우 아니다</td></tr><tr><td>오른쪽 끝</td><td>매우 그렇다</td></tr></tbody></table><p>설정한 문구는 설문에 등록된 모든 5점 척도형 질문에 공통 적용됩니다.</p><h3 id="_8-질문-수정-및-순서-변경" tabindex="-1">⑧ 질문 수정 및 순서 변경 <a class="header-anchor" href="#_8-질문-수정-및-순서-변경" aria-label="Permalink to &quot;⑧ 질문 수정 및 순서 변경&quot;">​</a></h3><p>등록한 질문은 수정, 복제, 삭제할 수 있습니다.</p><ul><li><strong>수정:</strong> 기존 질문 내용 또는 답변 유형 변경</li><li><strong>복제:</strong> 기존 질문과 동일한 질문 생성</li><li><strong>삭제:</strong> 불필요한 질문 제거</li><li><strong>순서 변경:</strong> 드래그하여 질문의 표시 순서 변경</li></ul><h3 id="_9-설문-저장-및-확인" tabindex="-1">⑨ 설문 저장 및 확인 <a class="header-anchor" href="#_9-설문-저장-및-확인" aria-label="Permalink to &quot;⑨ 설문 저장 및 확인&quot;">​</a></h3><ol><li>모든 설문 설정과 질문을 확인합니다.</li><li>화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</li><li>저장 확인 창에서 저장을 진행합니다.</li><li>방문객용 안내 페이지에서 설문을 확인합니다.</li><li>질문의 순서와 답변 유형이 정상적으로 표시되는지 점검합니다.</li></ol><blockquote><p><strong>주의사항</strong></p><p>설문을 공개하기 전에는 질문의 오탈자, 필수 응답 설정, 보기 항목 및 설문 기간을 반드시 확인해 주세요.</p></blockquote><h2 id="_8-4-오디오-가이드-등록-및-관리" tabindex="-1">8.4. 오디오 가이드 등록 및 관리 <a class="header-anchor" href="#_8-4-오디오-가이드-등록-및-관리" aria-label="Permalink to &quot;8.4. 오디오 가이드 등록 및 관리&quot;">​</a></h2><p>오디오 가이드는 방문객에게 행사 및 장소에 대한 설명을 음성으로 제공하는 기능입니다.</p><p>프로젝트 운영자는 안내할 콘텐츠의 스크립트를 작성하고, AI 음성 생성 기능을 이용하여 오디오 가이드를 제작할 수 있습니다.</p><p>또한 위치 정보를 설정하여 방문객이 특정 장소에 접근했을 때 음성 안내가 자동으로 재생되도록 구성할 수 있습니다.</p><h3 id="_1-오디오-가이드-관리-화면-이동" tabindex="-1">① 오디오 가이드 관리 화면 이동 <a class="header-anchor" href="#_1-오디오-가이드-관리-화면-이동" aria-label="Permalink to &quot;① 오디오 가이드 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>오디오 가이드</strong> 메뉴를 선택합니다.</li><li>등록된 오디오 가이드 목록을 확인합니다.</li><li>새로운 오디오 가이드를 등록하려면 추가 기능을 선택합니다.</li></ol><p><img src="'+s+'" alt="image.png"></p><h3 id="_2-오디오-가이드-기본-정보-설정" tabindex="-1">② 오디오 가이드 기본 정보 설정 <a class="header-anchor" href="#_2-오디오-가이드-기본-정보-설정" aria-label="Permalink to &quot;② 오디오 가이드 기본 정보 설정&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>제목</td><td>오디오 가이드의 이름</td></tr><tr><td>상태</td><td>준비 중, 공개, 비공개 상태 설정</td></tr><tr><td>연결 상세 콘텐츠</td><td>오디오 가이드와 관련된 상세 콘텐츠</td></tr><tr><td>위도</td><td>자동 재생 기준 위치의 위도</td></tr><tr><td>경도</td><td>자동 재생 기준 위치의 경도</td></tr><tr><td>자동 재생 범위</td><td>기준 위치에서 자동 재생할 거리(미터)</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>오디오 가이드 편집 화면으로 이동합니다.</li><li>제목을 입력합니다.</li><li>필요한 경우 상세 콘텐츠를 연결합니다.</li><li>위치 기반 안내를 사용할 경우 위도와 경도를 입력합니다.</li><li>자동 재생 범위를 설정합니다.</li></ol><p><img src="'+h+'" alt="image.png"></p><h3 id="_3-언어별-스크립트-작성" tabindex="-1">③ 언어별 스크립트 작성 <a class="header-anchor" href="#_3-언어별-스크립트-작성" aria-label="Permalink to &quot;③ 언어별 스크립트 작성&quot;">​</a></h3><p>스크립트는 오디오 가이드에서 음성으로 전달할 안내 문구입니다.</p><p>프로젝트에서 지원하는 언어에 맞춰 언어별 스크립트를 작성할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>오디오 가이드의 <strong>스크립트</strong> 영역으로 이동합니다.</li><li>작성할 언어를 선택합니다.</li><li>해당 언어의 안내 문구를 입력합니다.</li><li>필요한 경우 다른 언어의 스크립트도 작성합니다.</li><li>글자 수 및 입력 내용을 확인합니다.</li></ol><p><strong>스크립트 작성 예시</strong></p><p>&quot;이곳은 축제의 메인 공연장입니다. 매일 오후 다양한 공연과 특별 프로그램이 진행됩니다. 자세한 공연 일정은 행사 안내 페이지에서 확인하실 수 있습니다.&quot;</p><p><img src="'+p+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>음성으로 들었을 때 자연스럽게 이해할 수 있도록 짧고 명확한 문장으로 작성하는 것을 권장합니다.</p></blockquote><h3 id="_4-ai-음성-생성" tabindex="-1">④ AI 음성 생성 <a class="header-anchor" href="#_4-ai-음성-생성" aria-label="Permalink to &quot;④ AI 음성 생성&quot;">​</a></h3><p>작성한 스크립트를 바탕으로 AI 음성을 생성할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li><strong>음성</strong> 설정 영역으로 이동합니다.</li><li>사용할 성우를 선택합니다.</li><li>필요한 경우 음성 생성 프롬프트를 입력합니다.</li><li>음성 속도를 설정합니다.</li><li><strong>생성</strong> 버튼을 클릭합니다.</li><li>음성 생성 결과를 확인합니다.</li></ol><p><img src="'+g+'" alt="image.png"></p><h3 id="_5-음성-스타일-설정" tabindex="-1">⑤ 음성 스타일 설정 <a class="header-anchor" href="#_5-음성-스타일-설정" aria-label="Permalink to &quot;⑤ 음성 스타일 설정&quot;">​</a></h3><p>음성 생성 프롬프트를 이용하여 안내 음성의 스타일을 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>설정 요소</th><th>설명</th></tr></thead><tbody><tr><td>말하는 속도</td><td>빠르거나 느린 발화 속도</td></tr><tr><td>감정과 분위기</td><td>밝고 친근한 분위기, 차분한 안내 등</td></tr><tr><td>억양과 강조</td><td>중요한 정보의 강조 방식</td></tr><tr><td>호흡과 쉼</td><td>문장 사이의 자연스러운 간격</td></tr></tbody></table><p><strong>프롬프트 입력 예시</strong></p><p>&quot;친절하고 차분한 행사 안내원의 목소리로 읽어주세요. 문장 사이에 자연스러운 쉼을 두고, 장소명과 운영 시간을 또렷하게 발음해 주세요.&quot;</p><blockquote><p><strong>주의사항</strong></p><p>스크립트나 음성 속도를 변경한 경우 음성을 다시 생성해야 합니다.</p><p>음성이 생성되지 않은 상태에서는 저장할 수 없으므로 변경 후 반드시 음성을 재생성해 주세요.</p></blockquote><h3 id="_6-위치-기반-자동-재생-설정" tabindex="-1">⑥ 위치 기반 자동 재생 설정 <a class="header-anchor" href="#_6-위치-기반-자동-재생-설정" aria-label="Permalink to &quot;⑥ 위치 기반 자동 재생 설정&quot;">​</a></h3><p>특정 장소에 접근했을 때 오디오 가이드가 자동으로 재생되도록 위치와 범위를 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>위도</td><td>자동 재생 기준 장소의 위도</td></tr><tr><td>경도</td><td>자동 재생 기준 장소의 경도</td></tr><tr><td>자동 재생 범위</td><td>기준 장소로부터 자동 재생을 적용할 거리</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>자동 재생을 적용할 장소의 위도와 경도를 입력합니다.</li><li><strong>자동 재생 범위(미터)</strong> 를 설정합니다.</li><li>설정을 저장합니다.</li><li>현장에서 자동 재생 동작을 확인합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>자동 재생 범위를 <strong>0미터</strong>로 설정하면 자동 재생이 진행되지 않습니다.</p><p>위치 기반 기능은 방문객의 위치 권한과 실제 위치 정확도 등 사용 환경에 영향을 받을 수 있습니다.</p></blockquote><h3 id="_7-오디오-가이드-공개-설정" tabindex="-1">⑦ 오디오 가이드 공개 설정 <a class="header-anchor" href="#_7-오디오-가이드-공개-설정" aria-label="Permalink to &quot;⑦ 오디오 가이드 공개 설정&quot;">​</a></h3><p>오디오 가이드는 준비 상태에 따라 공개 여부를 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>상태</th><th>설명</th></tr></thead><tbody><tr><td>준비 중</td><td>필요한 음성이 모두 생성되지 않은 상태</td></tr><tr><td>공개</td><td>방문객에게 제공하도록 설정한 상태</td></tr><tr><td>비공개</td><td>방문객에게 제공하지 않도록 설정한 상태</td></tr></tbody></table><p>프로젝트에서 지원하는 언어 전체의 음성이 생성되면 공개 또는 비공개를 선택할 수 있습니다.</p><blockquote><p><strong>주의사항</strong></p><p>모든 지원 언어의 음성 생성이 완료되기 전에는 상태가 &#39;준비 중&#39;으로 고정됩니다.</p><p>공개 전 언어별 음성 생성 결과와 발음, 안내 내용을 확인해 주세요.</p></blockquote><hr><h2 id="_8-5-비디오-가이드-등록-및-관리" tabindex="-1">8.5. 비디오 가이드 등록 및 관리 <a class="header-anchor" href="#_8-5-비디오-가이드-등록-및-관리" aria-label="Permalink to &quot;8.5. 비디오 가이드 등록 및 관리&quot;">​</a></h2><p>비디오 가이드는 영상 콘텐츠를 통해 행사 또는 장소 관련 정보를 전달하는 기능입니다.</p><p>프로젝트 운영자는 비디오 가이드를 등록하고, 썸네일 및 언어별 영상 파일을 설정할 수 있습니다.</p><h3 id="_1-비디오-가이드-관리-화면-이동" tabindex="-1">① 비디오 가이드 관리 화면 이동 <a class="header-anchor" href="#_1-비디오-가이드-관리-화면-이동" aria-label="Permalink to &quot;① 비디오 가이드 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>비디오 가이드</strong> 메뉴를 선택합니다.</li><li>등록된 비디오 가이드 목록을 확인합니다.</li><li>새로운 비디오 가이드를 추가합니다.</li></ol><p><img src="'+b+'" alt="image.png"></p><h3 id="_2-비디오-가이드-기본-정보-입력" tabindex="-1">② 비디오 가이드 기본 정보 입력 <a class="header-anchor" href="#_2-비디오-가이드-기본-정보-입력" aria-label="Permalink to &quot;② 비디오 가이드 기본 정보 입력&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>이름</td><td>비디오 가이드의 이름</td></tr><tr><td>썸네일 이미지</td><td>영상 대표 이미지</td></tr><tr><td>언어별 영상</td><td>프로젝트 지원 언어에 맞는 영상 파일</td></tr><tr><td>연결된 상세 콘텐츠</td><td>비디오 가이드가 연결된 상세 콘텐츠</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>비디오 가이드를 추가합니다.</li><li>이름을 입력합니다.</li><li>썸네일 이미지를 등록합니다.</li><li>언어별 영상 파일을 등록합니다.</li><li>변경 내용을 저장합니다.</li></ol><h3 id="_3-썸네일-이미지-설정" tabindex="-1">③ 썸네일 이미지 설정 <a class="header-anchor" href="#_3-썸네일-이미지-설정" aria-label="Permalink to &quot;③ 썸네일 이미지 설정&quot;">​</a></h3><p>썸네일은 방문객이 영상 내용을 구분할 수 있도록 제공하는 대표 이미지입니다.</p><p>비디오가이드 업로드 시 썸네일 이미지가 생성되며, 필요할 경우 썸네일 이미지 교체가 가능합니다.</p><p><strong>설정 방법</strong></p><ol><li>비디오 가이드 편집 화면에서 썸네일 이미지 영역을 확인합니다.</li><li>이미지 파일을 선택합니다.</li><li>등록된 이미지를 확인합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><img src="'+c+'" alt="image.png"></p><h3 id="_4-언어별-영상-등록" tabindex="-1">④ 언어별 영상 등록 <a class="header-anchor" href="#_4-언어별-영상-등록" aria-label="Permalink to &quot;④ 언어별 영상 등록&quot;">​</a></h3><p>프로젝트에서 지원하는 언어별로 영상 파일을 등록할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li><strong>영상</strong> 설정 영역으로 이동합니다.</li><li>영상을 등록할 언어를 선택합니다.</li><li><strong>영상 파일 선택</strong> 버튼을 클릭합니다.</li><li>영상 파일을 업로드합니다.</li><li>업로드 완료 상태를 확인합니다.</li><li>필요한 경우 다른 언어의 영상도 등록합니다.</li><li>변경 내용을 저장합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>영상은 MP4 형식 사용을 권장합니다.</p><p>영상 업로드 중에는 작업이 완료될 때까지 업로드 상태를 확인해 주세요.</p></blockquote><h3 id="_5-상세-콘텐츠-연결" tabindex="-1">⑤ 상세 콘텐츠 연결 <a class="header-anchor" href="#_5-상세-콘텐츠-연결" aria-label="Permalink to &quot;⑤ 상세 콘텐츠 연결&quot;">​</a></h3><p>비디오 가이드는 상세 콘텐츠의 배너 영역에서 연결할 수 있습니다.</p><p><strong>설정 방법</strong></p><ol><li>프로젝트 관리 화면에서 <strong>상세 콘텐츠</strong> 메뉴로 이동합니다.</li><li>비디오 가이드를 연결할 상세 콘텐츠를 선택합니다.</li><li>상세 콘텐츠의 <strong>배너 영역</strong>으로 이동합니다.</li><li>해당 비디오 가이드를 연결합니다.</li><li>변경 내용을 저장합니다.</li></ol><p>비디오 가이드 관리 화면에서는 현재 연결된 상세 콘텐츠를 확인할 수 있습니다.</p><p><img src="'+u+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>비디오 가이드와 상세 콘텐츠의 연결은 비디오 가이드 편집 화면이 아니라 <strong>상세 콘텐츠 편집 &gt; 배너 영역</strong>에서 설정합니다.</p></blockquote><hr><h2 id="_8-6-부가-서비스-설정-확인" tabindex="-1">8.6. 부가 서비스 설정 확인 <a class="header-anchor" href="#_8-6-부가-서비스-설정-확인" aria-label="Permalink to &quot;8.6. 부가 서비스 설정 확인&quot;">​</a></h2><p>각 부가 서비스의 설정이 완료되면 실제 방문객용 안내 페이지에서 정상적으로 이용할 수 있는지 확인합니다.</p><h3 id="_1-ai-챗봇-확인" tabindex="-1">① AI 챗봇 확인 <a class="header-anchor" href="#_1-ai-챗봇-확인" aria-label="Permalink to &quot;① AI 챗봇 확인&quot;">​</a></h3><ul><li>챗봇 메뉴가 정상적으로 표시되는지 확인</li><li>질문 입력과 답변이 정상적으로 동작하는지 확인</li><li>행사 관련 정보가 올바르게 안내되는지 확인</li></ul><h3 id="_2-설문조사-확인" tabindex="-1">② 설문조사 확인 <a class="header-anchor" href="#_2-설문조사-확인" aria-label="Permalink to &quot;② 설문조사 확인&quot;">​</a></h3><ul><li>설문 공개 여부와 기간이 올바르게 설정되어 있는지 확인</li><li>단계별 질문이 정상적으로 표시되는지 확인</li><li>선택형, 서술형, 별점 및 5점 척도형 질문이 정상 동작하는지 확인</li><li>필수 질문에 대한 입력 검증이 정상적으로 동작하는지 확인</li></ul><h3 id="_3-오디오-가이드-확인" tabindex="-1">③ 오디오 가이드 확인 <a class="header-anchor" href="#_3-오디오-가이드-확인" aria-label="Permalink to &quot;③ 오디오 가이드 확인&quot;">​</a></h3><ul><li>언어별 스크립트가 정확하게 작성되었는지 확인</li><li>음성이 정상적으로 생성되었는지 확인</li><li>안내 음성의 발음과 속도가 적절한지 확인</li><li>공개 상태가 올바르게 설정되었는지 확인</li><li>위치 기반 자동 재생을 사용하는 경우 현장에서 정상 동작하는지 확인</li></ul><h3 id="_4-비디오-가이드-확인" tabindex="-1">④ 비디오 가이드 확인 <a class="header-anchor" href="#_4-비디오-가이드-확인" aria-label="Permalink to &quot;④ 비디오 가이드 확인&quot;">​</a></h3><ul><li>썸네일 이미지가 정상적으로 표시되는지 확인</li><li>언어별 영상 파일이 정상적으로 등록되었는지 확인</li><li>영상 재생이 정상적으로 동작하는지 확인</li><li>상세 콘텐츠와 올바르게 연결되어 있는지 확인</li></ul><blockquote><p><strong>참고</strong></p><p>부가 서비스는 사용자가 실제로 이용하는 환경에서 테스트하는 것을 권장합니다.</p><p>특히 위치 기반 오디오 가이드와 동영상 재생 기능은 모바일 기기, 네트워크 환경 및 접근 권한 등에 영향을 받을 수 있으므로 행사 시작 전 충분히 점검해 주세요.</p></blockquote>',151)])])}const y=a(_,[["render",m]]);export{I as __pageData,y as default};
